css:
.p08-e { --frame-w: var(--w2); }
.p08-status { display: flex; align-items: center; justify-content: center; gap: var(--s-2); padding: var(--s-5) var(--s-3); }
.p08-err { display: grid; gap: var(--s-3); justify-items: start; max-width: 32rem; margin-inline: auto; padding: var(--s-4) 0; }
.p08-err .banner { width: 100%; }
.p08-kept { display: grid; gap: var(--s-1); width: 100%; }
.p08-kept p { margin: 0; }
.p08-keptbox { display: grid; gap: var(--s-1); padding: var(--s-2) var(--s-3); user-select: text; font-size: var(--fs-small); line-height: var(--lh-small); overflow-wrap: anywhere; }
.p08-top { display: grid; gap: var(--s-2); }
.p08-top:empty { display: none; }
.p08-btnwrap { position: relative; display: inline-block; }
.p08-tip { position: absolute; z-index: 30; width: max-content; max-width: 17.5rem; }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p08-expl { flex: 1; display: grid; gap: var(--s-1); max-width: var(--measure); }

.content.p08-page { padding: var(--s-3); min-height: 100%; display: flex; flex-direction: column; gap: var(--s-3); }
@media (min-width: 48rem) and (min-height: 31.25rem) { .content.p08-page { padding: var(--s-4) var(--s-5); } }
.p08-col { display: grid; gap: var(--s-4); width: 100%; max-width: 40rem; margin-inline: auto; align-content: start; }
.p08-head { display: grid; gap: var(--s-1); }
.p08-sub { overflow-wrap: anywhere; }
.p08-foot { position: sticky; bottom: 0; z-index: 1; display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2) var(--s-3); margin: auto calc(var(--s-3) * -1) calc(var(--s-3) * -1); padding: var(--s-3); background: var(--white); border-top: var(--w1) solid var(--rule); }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p08-foot { margin: auto calc(var(--s-5) * -1) calc(var(--s-4) * -1); padding: var(--s-3) var(--s-5); } }
.p08-foot > .p08-foot-in { margin: 0 auto; }
.p08-foot-in { display: flex; flex-wrap: nowrap; gap: var(--s-2); width: 100%; max-width: 40rem; }
.p08-foot-in .btn { flex: 0 1 auto; }
.p08-foot-in .btn--primary { flex: 1 1 auto; }

.p08-foot-in .btn--danger { margin-inline: 0 var(--s-2); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p08-foot-in { flex-wrap: wrap; } .p08-foot-in .btn--danger { flex: 1 1 100%; margin: 0 0 var(--s-2); } }
.textarea.p08-name { min-height: var(--ctl-h); padding: var(--s-2) var(--s-3); resize: none; overflow-wrap: anywhere; }
.textarea.p08-desc { min-height: calc(var(--ctl-h) * 4); resize: none; }
.p08-area { position: relative; }
.field__count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.p08-focus, .textarea.p08-focus, .input.p08-focus { border: var(--w2) solid var(--blue); padding-inline: calc(var(--s-3) - var(--w1)); }
.p08-row2 { display: grid; grid-template-columns: minmax(0, 18rem) minmax(0, 1fr); gap: var(--s-3); align-items: start; }
@media (max-width: 38rem) { .p08-row2 { grid-template-columns: minmax(0, 1fr); } }
.p08-wrap { position: relative; display: grid; gap: var(--s-1); }
.p08-date { display: flex; align-items: center; gap: var(--s-2); }
.p08-date .input { flex: 1 1 auto; min-width: 0; max-width: 11rem; }
.p08-menu { position: absolute; z-index: 20; left: 0; right: 0; bottom: calc(100% + var(--s-1)); max-height: min(22rem, 60cqh); overflow: auto; }
.p08-sec { padding: var(--s-1) var(--s-3) 0; font-size: var(--fs-cap); line-height: var(--lh-cap); font-weight: var(--fw-bold); color: var(--muted); }
.select[disabled], .select[aria-disabled="true"] { border-color: var(--c-disabled-border); color: var(--c-disabled-text); cursor: not-allowed; }
.p08-cal { position: absolute; z-index: 20; left: 0; top: calc(100% + var(--s-1)); width: min(19rem, 100%); min-width: 17rem; padding: var(--s-2); }
.p08-cal__head { display: flex; align-items: center; justify-content: space-between; gap: var(--s-2); }
.p08-cal__title { font-weight: var(--fw-bold); font-size: var(--fs-small); }
.p08-cal__grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: var(--w2); text-align: center; }
.p08-cal__dow { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); padding: var(--s-1) 0; }
.p08-cal__day { min-height: var(--hit); padding: 0; border: var(--w1) solid transparent; border-radius: var(--r); background: transparent; font-size: var(--fs-small); font-variant-numeric: tabular-nums; }
.p08-cal__day[aria-selected="true"] { border: var(--w2) solid var(--blue); color: var(--blue); font-weight: var(--fw-bold); }
.p08-cal__day[disabled] { visibility: hidden; }
.p08-note { padding: var(--s-6) var(--s-3); display: grid; justify-items: center; gap: var(--s-3); }
.p08-added { color: var(--text-2); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
.dialog__foot.p08-lvfoot { flex-direction: column; }
.p08-lvfoot > * { flex: none; }
.textarea.p08-name { field-sizing: content; }
.p08-page .p08-err { width: 100%; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p08-shift .p08-col { margin-top: calc(var(--p08-shift, 0rem) * -1); } }
.p08-tipline { flex: 1 1 100%; display: flex; justify-content: flex-end; }
